CREATE TABLE t0 (c0, c2, c3); SELECT subq10.c17 FROM (SELECT c8 AS c14, TRUE AS c16, c10 AS c17 FROM (SELECT t59.c3, t59.c3 AS c6, t59.c2 AS c8, t59.c0 AS c10, t59.c3 FROM t0 AS t59 LEFT OUTER JOIN t0 AS _t0 ON (NOT t59.c3 IS NULL) WHERE t59.c3 > t59.c2 ORDER BY c6 ASC) ORDER BY c16 ASC) AS subq10 WHERE 51 < c14 OR c17 = CASE c16 WHEN subq10.c16 IS NULL THEN c16 ELSE c16 END